# UARD (Untrapped Auto-Repair Diagnostic) ver 1.0.4 - TRUE BASELINE
# Defensive baseline: known failure classes are trapped, classified and reported.
$ErrorActionPreference='Stop'
$UARDName='UARD (Untrapped Auto-Repair Diagnostic)';$UARDVersion='1.0.4';$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$Middleman='https://untrapped-update-middleman-000-999-production.up.railway.app';$ArtifactBase=$Middleman+'/v1/artifact/';$Report=Join-Path $Root 'repair-success-latest.txt';$BackupRoot=Join-Path $Root 'repair-backups';$log=New-Object 'System.Collections.Generic.List[string]';$changed=$false;$failed=$false;$unknown=$false;$CanonicalCache=@{};$sw=[Diagnostics.Stopwatch]::StartNew();$MaxBytes=8388608;$ExpectedVersion='3.2.0';$ExpectedProtocol=3;$ExpectedBaseline='1.0.0'
function Log([string]$m){$x='['+(Get-Date -Format HH:mm:ss)+'] '+$m;Write-Host $x;[void]$log.Add($x)}
function HashBytes([byte[]]$b){$s=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($s.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}
function Normalize([byte[]]$b,[string]$n,[string]$t){if($t -eq 'json'){try{$null=([Text.Encoding]::UTF8.GetString($b).TrimStart([char]0xFEFF)|ConvertFrom-Json -ErrorAction Stop)}catch{throw "invalid canonical JSON for $n"};return $b};$s=[Text.Encoding]::UTF8.GetString($b).TrimStart([char]0xFEFF).Trim();if(-not $s.StartsWith('{')){return $b};try{$j=$s|ConvertFrom-Json -ErrorAction Stop}catch{return $b};if($null -eq $j -or $j -isnot [psobject]){return $b};$lang='';if($j.PSObject.Properties.Name -contains 'language'){$lang=[string]$j.language}elseif($j.PSObject.Properties.Name -contains 'lang'){$lang=[string]$j.lang};$explicit=$lang.ToLowerInvariant() -in @('powershell','powershell-script','powershellscript','ps1','pwsh');if(-not $explicit){return $b};$enc='';if($j.PSObject.Properties.Name -contains 'encoding'){$enc=[string]$j.encoding};foreach($k in @('powershell','script','source','code','content','text','body')){if($j.PSObject.Properties.Name -contains $k -and $j.$k -is [string]){$v=[string]$j.$k;if($enc.ToLowerInvariant().Replace('-','') -eq 'base64'){$v=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($v))};return [Text.Encoding]::UTF8.GetBytes($v.TrimEnd()+"`n")}};if($j.PSObject.Properties.Name -contains 'commands' -and $j.commands -is [array] -and @($j.commands|Where-Object{$_ -isnot [string]}).Count -eq 0){return [Text.Encoding]::UTF8.GetBytes((($j.commands -join "`n").TrimEnd()+"`n"))};return $b}
function ReadLimited([IO.Stream]$st){$ms=New-Object IO.MemoryStream;$buf=New-Object byte[] 65536;$total=0;try{while(($r=$st.Read($buf,0,$buf.Length)) -gt 0){$total+=$r;if($total -gt $MaxBytes){throw "canonical artifact exceeds $MaxBytes byte limit"};$ms.Write($buf,0,$r)};return $ms.ToArray()}finally{$ms.Dispose()}}
function RemoteBytes([string]$n,[string]$t){if($CanonicalCache.ContainsKey($n)){return $CanonicalCache[$n]};for($a=1;$a -le 5;$a++){try{Log ('FETCH '+$n+' attempt '+$a+'/5');$uri=$ArtifactBase+$n+'?cb='+[DateTime]::UtcNow.Ticks;$q=[Net.HttpWebRequest]::Create($uri);$q.Method='GET';$q.Timeout=30000;$q.ReadWriteTimeout=30000;$q.UserAgent='UARD/1.0.4';$q.AllowAutoRedirect=$false;$r=$q.GetResponse();try{$v=[string]$r.Headers['X-Untrapped-Version'];$pr=[int]$r.Headers['X-Untrapped-Protocol'];$bl=[string]$r.Headers['X-Untrapped-Baseline'];if($v -ne $ExpectedVersion -or $pr -ne $ExpectedProtocol -or $bl -ne $ExpectedBaseline){throw "middleman identity mismatch: version=$v protocol=$pr baseline=$bl"};if($r.ContentLength -gt $MaxBytes){throw "canonical artifact exceeds $MaxBytes byte limit"};$raw=ReadLimited $r.GetResponseStream();$sha=[string]$r.Headers['X-Untrapped-SHA256'];if($sha -and $sha -ne (HashBytes $raw)){throw 'middleman SHA256 header mismatch'};$x=Normalize $raw $n $t}finally{$r.Dispose()};$CanonicalCache[$n]=$x;Log ('DOWNLOAD OK '+$n+' '+$x.Length+' bytes SHA256='+(HashBytes $x));return $x}catch{$c=0;$detail=$_.Exception.Message;$resp=$_.Exception.Response;try{$c=[int]$resp.StatusCode}catch{};try{$fc=[string]$resp.Headers['X-Untrapped-Failure-Class'];if($fc){$detail=$detail+' failure-class='+$fc}}catch{};if($c -eq 409){Log ('HTTP 409 CONFLICT '+$n+': deterministic resource-state conflict; refusing blind retry.');$script:unknown=$true;break};if($c -eq 422){Log ('HTTP 422 UNPROCESSABLE '+$n+': deterministic request/content rejection; refusing blind retry.');$script:failed=$true;break};if($c -eq 404){Log ('HTTP 404 NOT FOUND '+$n+': canonical artifact absent.');$script:unknown=$true;break};if($c -eq 401 -or $c -eq 403){Log ('HTTP '+$c+' ACCESS DENIED '+$n+': policy/authentication/access issue; not bypassing it.');$script:unknown=$true;break};if($c -eq 301 -or $c -eq 302 -or $c -eq 307 -or $c -eq 308){Log ('REDIRECT REJECTED '+$n+': canonical endpoint redirected; refusing unexpected host.');$script:unknown=$true;break};if($c -eq 408 -or $c -eq 425 -or $c -eq 429 -or $c -ge 500 -or $c -eq 0){Log ('TRANSIENT FETCH ERROR '+$n+' HTTP '+$c+'; retrying. '+$detail);if($a -lt 5){Start-Sleep -Seconds ([Math]::Min($a*2,8));continue}}else{Log ('CANONICAL FETCH ERROR '+$n+' HTTP '+$c+': '+$detail)};break}};$script:unknown=$true;Log ('UNVERIFIED '+$n+' canonical source unavailable.');return $null}
function ValidPS([byte[]]$b,[string]$n){if($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage'){Log ('SCRIPT SYNTAX CHECK LIMITED '+$n+': LanguageMode='+$ExecutionContext.SessionState.LanguageMode);$script:unknown=$true;return $true};try{$s=[Text.Encoding]::UTF8.GetString($b);$null=[scriptblock]::Create($s);return $true}catch{Log ('SCRIPT VALIDATION FAILED '+$n+': '+$_.Exception.Message);return $false}}
function Backup([string]$p){if(Test-Path -LiteralPath $p){$d=Join-Path $BackupRoot (Get-Date -Format 'yyyyMMdd-HHmmssfff');New-Item -ItemType Directory -Path $d -Force|Out-Null;Copy-Item -LiteralPath $p -Destination (Join-Path $d (Split-Path $p -Leaf)) -Force;Log ('BACKUP '+$p)}}
function Install([string]$p,[byte[]]$b){$d=Split-Path -Parent $p;if(-not(Test-Path -LiteralPath $d)){New-Item -ItemType Directory -Path $d -Force|Out-Null};$tmp=$p+'.uaudtmp-'+[Guid]::NewGuid().ToString('N');try{[IO.File]::WriteAllBytes($tmp,$b);$verify=[IO.File]::ReadAllBytes($tmp);if((HashBytes $verify) -ne (HashBytes $b)){throw 'temporary write verification hash mismatch'};Move-Item -LiteralPath $tmp -Destination $p -Force}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}}
function PolicyDiag{$l=Get-ExecutionPolicy -List|Out-String;Log ('EXECUTION POLICY '+(($l.Trim()-replace '\r?\n',' | ')));$mp=(Get-ExecutionPolicy -Scope MachinePolicy);$up=(Get-ExecutionPolicy -Scope UserPolicy);if($mp -ne 'Undefined' -or $up -ne 'Undefined'){Log 'GROUP POLICY EXECUTION POLICY DETECTED: process Bypass cannot override MachinePolicy/UserPolicy.';$script:unknown=$true};$lm=$ExecutionContext.SessionState.LanguageMode;Log ('LANGUAGE MODE '+$lm);if($lm -ne 'FullLanguage'){Log 'APPLICATION CONTROL / CONSTRAINED LANGUAGE DETECTED; repair will not attempt to bypass it.';$script:unknown=$true};try{$zone=Get-Item -LiteralPath $PSCommandPath -Stream Zone.Identifier -ErrorAction SilentlyContinue;if($zone){Log 'ZONE.IDENTIFIER PRESENT; attempting local unblock.';try{Unblock-File -LiteralPath $PSCommandPath -ErrorAction Stop;Log 'UNBLOCK OK'}catch{Log ('UNBLOCK FAILED: '+$_.Exception.Message);$script:unknown=$true}}else{Log 'ZONE.IDENTIFIER NOT PRESENT'}}catch{Log ('ZONE CHECK UNAVAILABLE: '+$_.Exception.Message);$script:unknown=$true}}
function ToolDiag{$ps=Get-Command powershell.exe -ErrorAction SilentlyContinue;if($ps){Log ('POWERSHELL '+$ps.Source)}else{Log 'POWERSHELL.EXE NOT FOUND';$script:failed=$true};if(-not(Get-Command cmd.exe -ErrorAction SilentlyContinue)){Log 'CMD.EXE NOT FOUND';$script:unknown=$true}}
function WriteReportSafe([string]$diagnosis){try{$reportText=@($UARDName+' ver '+$UARDVersion+' - TRUE BASELINE','Run: '+(Get-Date),'Diagnosis: '+$diagnosis,'Middleman: '+$Middleman,'Execution-policy and application-control diagnostics captured.','Known deterministic/transient HTTP classes handled explicitly.','Middleman identity and artifact hash checked.','Protected boundary unchanged.','',$log);$reportText|Set-Content -LiteralPath $Report -Encoding UTF8;try{Start-Process notepad.exe -ArgumentList @($Report)|Out-Null}catch{Log ('NOTEPAD LAUNCH FAILED: '+$_.Exception.Message)}}catch{Log ('REPORT WRITE FAILED: '+$_.Exception.Message)}}
try{
Log ($UARDName+' ver '+$UARDVersion+' - TRUE BASELINE');Log ('MIDDLEMAN '+$Middleman);Log 'PROTECTION: no Windows Firewall/WFP/DNS/routes/Hosts/proxy/VPN/adapter/override-policy changes.';PolicyDiag;ToolDiag
$core=@('config.json','packet-filter.ps1','self-repair.ps1','status-untrapped.ps1','ultra-mode.ps1');foreach($n in $core){$p=Join-Path $Root $n;$t=if($n -eq 'config.json'){'json'}else{'ps1'};try{$x=RemoteBytes ('ultra-mode/'+$n) $t}catch{Log ('ARTIFACT EXCEPTION '+$n+': '+$_.Exception.Message);$script:failed=$true;continue};if($null -eq $x){continue};if($t -eq 'ps1' -and -not(ValidPS $x $n)){$script:failed=$true;continue};try{$cur=if(Test-Path -LiteralPath $p){[IO.File]::ReadAllBytes($p)}else{$null};if($null -eq $cur -or (HashBytes $cur) -ne (HashBytes $x)){Backup $p;Install $p $x;$script:changed=$true;Log ('REPAIRED '+$n)}else{Log ('CURRENT '+$n)}}catch{Log ('LOCAL REPAIR ERROR '+$n+': '+$_.Exception.Message);$script:failed=$true}}
foreach($n in @('WinDivert.dll','WinDivert64.sys')){$f=Get-ChildItem -LiteralPath $Root -Filter $n -File -Recurse -ErrorAction SilentlyContinue|Select-Object -First 1;if($f){Log ('NATIVE OK '+$n)}else{Log ('NATIVE MISSING '+$n);$script:failed=$true}}
try{$probe=Join-Path $Root ('.uaud-write-test-'+[Guid]::NewGuid().ToString('N'));[IO.File]::WriteAllText($probe,'ok');if((Get-Content -LiteralPath $probe -Raw) -ne 'ok'){throw 'write/read verification mismatch'};Remove-Item $probe -Force;Log 'WRITE ACCESS OK'}catch{Log ('WRITE ACCESS FAILED: '+$_.Exception.Message);$script:failed=$true}
$diagnosis='NO REPAIR REQUIRED';if($failed){$diagnosis='REPAIR INCOMPLETE'}elseif($unknown){$diagnosis='VERIFICATION INCOMPLETE'}elseif($changed){$diagnosis='REPAIR SUCCESS'};Log ('[DIAGNOSIS] '+$diagnosis);$sw.Stop();Log ('RUNTIME '+$sw.Elapsed.ToString());if($changed -or $failed -or $unknown){WriteReportSafe $diagnosis};if($failed){exit 1};if($unknown){exit 2};exit 0
}catch{try{Log ('FATAL GUARD: '+$_.Exception.GetType().FullName+': '+$_.Exception.Message)}catch{};$sw.Stop();$script:failed=$true;WriteReportSafe 'FATAL GUARD TRIPPED';exit 1
}
